fn solve(input: Vec<char>) -> Vec<char> {
    // Step 1: Copy input since we need to mutate it
    let mut chars = input;

    // Remove trailing newline '\n' if present
    if let Some(&last) = chars.last() {
        if last == '\n' {
            chars.pop();
        }
    }

    // Define whitespace chars
    fn is_whitespace(c: char) -> bool {
        c == ' ' || c == '\t' || c == '\n' || c == '\r'
    }

    // Trim leading whitespace
    let start = chars.iter().position(|&c| !is_whitespace(c)).unwrap_or(chars.len());
    // Trim trailing whitespace
    let end = chars.iter().rposition(|&c| !is_whitespace(c)).unwrap_or(0);

    // Slice the trimmed chars safely, if start > end result is empty vec
    let trimmed = if start <= end {
        chars[start..=end].to_vec()
    } else {
        Vec::new()
    };

    // Validate password properties
    if trimmed.len() >= 5
        && trimmed.iter().any(|&c| ('a'..='z').contains(&c))
        && trimmed.iter().any(|&c| ('A'..='Z').contains(&c))
        && trimmed.iter().any(|&c| ('0'..='9').contains(&c))
    {
        // Valid password
        "Correct\n".chars().collect()
    } else {
        // Invalid password
        "Too weak\n".chars().collect()
    }
}